try {
  const sources = value.mode === 'normal' ? dispatchedMemorySources(request.messages) : []
  const evidence = (state: 'DISPATCH_STARTED' | 'RESPONSE_OBSERVED') => {
    if (sources.length) recordMemoryEvidence(this.store, value.assistantId, value.requestId, sources, state)
  }
  evidence('DISPATCH_STARTED')
  let observed = false
  const observe = () => {
    if (!observed) { evidence('RESPONSE_OBSERVED'); observed = true }
  }
  const result = await this.transport({
    ...request,
    onDelta: request.onDelta ? (delta) => { observe(); request.onDelta!(delta) } : undefined
  })
  if (result.status === 'completed' || result.text.length > 0) observe()
  this.operations.settle(attempt, result.usage)
